import urllib.request, concurrent.futures
from bs4 import BeautifulSoup
urls=['https://edu.hnu.edu.cn/info/1151/5943.htm','https://edu.muc.edu.cn/info/1039/8828.htm','https://fe.bnu.edu.cn/zdgz/572c14ab984b477e9cbfe45699c1f1ac.htm','https://ed.ecnu.edu.cn/c4/00/c45969a771072/page.htm','https://lifescience.hunnu.edu.cn/info/1078/8218.htm']
def get(u):
 try:
  raw=urllib.request.urlopen(u,timeout=25).read().decode('utf-8','replace'); s=BeautifulSoup(raw,'html.parser')
  for t in s(['script','style']): t.decompose()
  lines=s.get_text('\\n',strip=True).splitlines()
  matched=[(i,l) for i,l in enumerate(lines) if any(w in l for w in ['申请条件','六级','四级','报名条件','职业技术','成人教育','附件','相关专业','0401','425','外语'])]
  return u,[(i,' '.join(lines[max(0,i-1):min(len(lines),i+4)])) for i,l in matched],[(a.get_text(strip=True),a.get('href')) for a in s.find_all('a') if any(w in a.get_text() for w in ['附件','预报名通知','招生录取工作办法'])]
 except Exception as e: return u,str(e)
for r in concurrent.futures.ThreadPoolExecutor(5).map(get,urls): print(r)
PY"

